import type { RituelKeyword } from "./022-invocation-system";

export interface SonicSignature {
  readonly keyword:    RituelKeyword;
  readonly startFreq:  number;   // Hz
  readonly endFreq:    number;   // Hz — même que start si ton tenu
  readonly duration:   number;   // ms
  readonly shape:      string;   // wave shape
  readonly description: string;
}

export const RITUAL_SOUNDS: readonly SonicSignature[] = Object.freeze([
  { keyword: "RÉVEIL",     startFreq: 432, endFreq: 639, duration: 1200, shape: "sine",     description: "Montée douce du sol vers le cœur" },
  { keyword: "SOMMEIL",    startFreq: 639, endFreq: 432, duration: 1800, shape: "sine",     description: "Descente apaisante vers le repos" },
  { keyword: "CHAOS",      startFreq: 639, endFreq: 741, duration:  800, shape: "sawtooth", description: "Explosion harmonique soudaine" },
  { keyword: "HARMONIE",   startFreq: 528, endFreq: 639, duration: 2000, shape: "sine",     description: "Accord parfait — 528 + 639 + 741" },
  { keyword: "ATTRACTION", startFreq: 741, endFreq: 528, duration: 1000, shape: "triangle", description: "Convergence — les harmoniques se rapprochent" },
  { keyword: "RÉPULSION",  startFreq: 528, endFreq: 741, duration: 1000, shape: "triangle", description: "Dispersion — les harmoniques s'écartent" },
  { keyword: "AURORE",     startFreq: 396, endFreq: 963, duration: 3000, shape: "sine",     description: "Balayage complet du spectre Solfège" },
  { keyword: "RÉPARATION", startFreq: 417, endFreq: 528, duration: 2500, shape: "sine",     description: "Retour à l'accord fondamental — réparation douce" },
]);

