#[derive(Debug, Clone)]
pub struct SonicSignature {
    pub keyword:     String,
    pub start_freq:  f64,
    pub end_freq:    f64,
    pub duration_ms: u32,
    pub shape:       String,
    pub description: String,
}

pub fn ritual_sound(keyword: &str) -> Option<SonicSignature> {
    match keyword {
        "RÉVEIL"     => Some(SonicSignature { keyword: keyword.into(), start_freq: 432.0, end_freq: 639.0, duration_ms: 1200, shape: "sine".into(),     description: "Montée douce du sol vers le cœur".into() }),
        "SOMMEIL"    => Some(SonicSignature { keyword: keyword.into(), start_freq: 639.0, end_freq: 432.0, duration_ms: 1800, shape: "sine".into(),     description: "Descente apaisante".into() }),
        "CHAOS"      => Some(SonicSignature { keyword: keyword.into(), start_freq: 639.0, end_freq: 741.0, duration_ms:  800, shape: "sawtooth".into(), description: "Explosion harmonique".into() }),
        "HARMONIE"   => Some(SonicSignature { keyword: keyword.into(), start_freq: 528.0, end_freq: 639.0, duration_ms: 2000, shape: "sine".into(),     description: "Accord parfait".into() }),
        "RÉPARATION" => Some(SonicSignature { keyword: keyword.into(), start_freq: 417.0, end_freq: 528.0, duration_ms: 2500, shape: "sine".into(),     description: "Retour à l'accord fondamental".into() }),
        _ => None,
    }
}
